 std::vector<double> Matrix::SumPerColumn() const {
     std::vector<double> result(cols_, 0.0);
-    for (std::size_t c = 0; c < cols_; ++c) {
-        double s = 0.0;
-        for (std::size_t r = 0; r < rows_; ++r) {
-            s += at(r, c);
-        }
-        result[c] = s;
+    // Walk rows in the outer loop and columns in the inner loop so that
+    // successive accesses are to adjacent doubles in memory. This is
+    // row-major order over the contiguous backing storage and avoids the
+    // cols_-strided pattern of the column-major variant above.
+    for (std::size_t r = 0; r < rows_; ++r) {
+        const std::size_t base = r * cols_;
+        for (std::size_t c = 0; c < cols_; ++c) {
+            result[c] += data_[base + c];
+        }
     }
     return result;
 }
